import React from 'react';
import { Link } from 'react-router-dom';

const Stars = ({ rating }) => (
  <div className="stars">
    {[1,2,3,4,5].map(i => (
      <span key={i} className={`star ${i <= Math.round(rating) ? 'filled' : ''}`}>★</span>
    ))}
  </div>
);

// Deterministic gradient from title string
function getCourseGradient(title = '', category = '') {
  const seed = (title + category).split('').reduce((a, c) => a + c.charCodeAt(0), 0);
  const gradients = [
    ['#7c3aed', '#2563eb', '#0f172a'],
    ['#db2777', '#7c3aed', '#0f172a'],
    ['#059669', '#0891b2', '#0f172a'],
    ['#d97706', '#dc2626', '#0f172a'],
    ['#7c3aed', '#ec4899', '#0f172a'],
    ['#0891b2', '#7c3aed', '#0f172a'],
    ['#16a34a', '#7c3aed', '#0f172a'],
    ['#ea580c', '#7c3aed', '#0f172a'],
  ];
  const [a, b, bg] = gradients[seed % gradients.length];

  // Decorative shapes using the seed
  const shapes = [
    { cx: 30 + (seed % 40), cy: 30 + (seed % 30), r: 60 + (seed % 40) },
    { cx: 120 + (seed % 80), cy: 80 + (seed % 50), r: 80 + (seed % 30) },
    { cx: 220 + (seed % 60), cy: 20 + (seed % 60), r: 50 + (seed % 40) },
  ];

  return { a, b, bg, shapes };
}

// First two words of title as a visual label
function getTitleAbbrev(title = '') {
  return title.split(' ').slice(0, 2).join(' ').toUpperCase();
}

export default function CourseCard({ course, delay = 0 }) {
  const levelColors = { beginner: 'badge-neon', intermediate: 'badge-purple', advanced: 'badge-pink' };
  const { a, b, bg, shapes } = getCourseGradient(course.title, course.category);

  return (
    <Link to={`/courses/${course._id}`}
      style={{
        display: 'block', textDecoration: 'none', borderRadius: 16, overflow: 'hidden',
        animation: `fadeUp 0.6s ease ${delay}s both`,
        background: 'rgba(14,11,30,0.7)', border: '1px solid rgba(124,58,237,0.2)',
        transition: 'all 0.35s ease',
      }}
      onMouseEnter={e => {
        e.currentTarget.style.transform = 'translateY(-6px)';
        e.currentTarget.style.borderColor = 'rgba(124,58,237,0.5)';
        e.currentTarget.style.boxShadow = '0 20px 60px rgba(124,58,237,0.2)';
      }}
      onMouseLeave={e => {
        e.currentTarget.style.transform = 'translateY(0)';
        e.currentTarget.style.borderColor = 'rgba(124,58,237,0.2)';
        e.currentTarget.style.boxShadow = 'none';
      }}>

      {/* Thumbnail */}
      <div style={{ position: 'relative', height: 180, overflow: 'hidden', background: bg }}>
        {course.thumbnail ? (
          <img src={`http://localhost:5000/${course.thumbnail}`} alt={course.title}
            style={{ width: '100%', height: '100%', objectFit: 'cover', transition: 'transform 0.4s' }} />
        ) : (
          /* Dynamic gradient thumbnail */
          <svg width="100%" height="100%" viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style={{ display: 'block' }}>
            <defs>
              <linearGradient id={`g-${course._id}`} x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor={a} stopOpacity="0.9" />
                <stop offset="100%" stopColor={b} stopOpacity="0.9" />
              </linearGradient>
              <filter id={`blur-${course._id}`}>
                <feGaussianBlur stdDeviation="28" />
              </filter>
            </defs>

            {/* Background */}
            <rect width="320" height="180" fill={bg} />

            {/* Blurred glow orbs */}
            {shapes.map((s, i) => (
              <circle key={i} cx={s.cx} cy={s.cy} r={s.r}
                fill={i % 2 === 0 ? a : b} opacity="0.35"
                filter={`url(#blur-${course._id})`} />
            ))}

            {/* Subtle grid lines */}
            <g stroke="rgba(255,255,255,0.04)" strokeWidth="1">
              {[40, 80, 120, 160, 200, 240, 280].map(x => (
                <line key={x} x1={x} y1="0" x2={x} y2="180" />
              ))}
              {[36, 72, 108, 144].map(y => (
                <line key={y} x1="0" y1={y} x2="320" y2={y} />
              ))}
            </g>

            {/* Gradient overlay pill */}
            <rect x="20" y="126" width="280" height="36" rx="8"
              fill={`url(#g-${course._id})`} opacity="0.15" />

            {/* Course title abbreviation */}
            <text x="160" y="98" textAnchor="middle" dominantBaseline="middle"
              fontFamily="system-ui, -apple-system, sans-serif"
              fontSize="13" fontWeight="700" letterSpacing="2"
              fill="rgba(255,255,255,0.18)">
              {getTitleAbbrev(course.title)}
            </text>

            {/* Accent line at bottom */}
            <rect x="0" y="174" width="320" height="3"
              fill={`url(#g-${course._id})`} opacity="0.8" />
          </svg>
        )}

        {/* Category badge */}
        <div style={{
          position: 'absolute', top: 12, left: 12,
          background: 'rgba(0,0,0,0.55)', backdropFilter: 'blur(8px)',
          padding: '4px 10px', borderRadius: 100, fontSize: 11, fontWeight: 700,
          color: '#c084fc', border: '1px solid rgba(124,58,237,0.3)'
        }}>{course.category}</div>

        {course.price === 0 && (
          <div style={{
            position: 'absolute', top: 12, right: 12,
            background: 'linear-gradient(135deg, #00f5d4, #7c3aed)',
            padding: '4px 10px', borderRadius: 100, fontSize: 11, fontWeight: 700, color: 'white'
          }}>FREE</div>
        )}
      </div>

      {/* Content */}
      <div style={{ padding: '18px 20px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
          <span className={`badge ${levelColors[course.level] || 'badge-purple'}`}>{course.level}</span>
        </div>

        <h3 style={{ fontSize: 16, fontWeight: 700, color: '#f0eeff', lineHeight: 1.4, marginBottom: 8,
          display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
          {course.title}
        </h3>

        <p style={{ fontSize: 13, color: '#6b6490', marginBottom: 14, lineHeight: 1.5,
          display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
          {course.shortDescription || course.description}
        </p>

        <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 14 }}>
          <div style={{ width: 28, height: 28, borderRadius: '50%', background: 'linear-gradient(135deg, #7c3aed, #a855f7)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 11, fontWeight: 700, color: 'white' }}>
            {course.instructor?.name?.charAt(0) || 'I'}
          </div>
          <span style={{ fontSize: 13, color: '#b8b0d8' }}>{course.instructor?.name || 'Instructor'}</span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 14 }}>
          <Stars rating={course.averageRating || 0} />
          <span style={{ fontSize: 13, color: '#ffd700', fontWeight: 700 }}>{course.averageRating?.toFixed(1) || '0.0'}</span>
          <span style={{ fontSize: 12, color: '#6b6490' }}>({course.reviews?.length || 0})</span>
        </div>

        {/* Price only — no students/modules */}
        <div style={{ borderTop: '1px solid rgba(124,58,237,0.1)', paddingTop: 14 }}>
          <div style={{ fontSize: 18, fontWeight: 800, color: course.price === 0 ? '#00f5d4' : '#c084fc' }}>
            {course.price === 0 ? 'Free' : `$${course.price}`}
          </div>
        </div>
      </div>
    </Link>
  );
}
